insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$tangua$q$, $q$https://tangua.rj.gov.br/home/wp-content/uploads/2021/03/Gabinete-do-Prefeito.pdf (Decreto 29/2021) ; https://tangua.rj.gov.br/prefeitura-define-novas-regras-para-trafego-de-veiculos-pesados-no-centro/ (divulgação)$q$, $q$Ato oficial de Tanguá: domínio público (Lei 9.610/1998, art. 8º, IV). Geometria: OpenStreetMap (ODbL 1.0, © colaboradores do OSM), vias casadas por nome.$q$, 28, $q$Decreto 29/2021, art. 1º: nas vias internas do perímetro formado pela via interior do Viaduto (BR-101, km 274) e sete ruas do centro, veículos com lotação acima de 5 t ou mais de 6,50 m ficam proibidos (seg-sex 7h-20h, sáb 7h-15h) e carretas e cavalos mecânicos em qualquer horário. Três das sete ruas (David Beloniel, Valdomiro Rosa, Augusto da Rocha) não têm nome no OSM e a via interior do Viaduto não é identificável: ficam sem geometria (pendência). Revogação não localizada, mas sem diário oficial acessível: confiança média.$q$);
